import * as W from './world.mjs';
export function createPartyVisionCache(perceive=W.perception){let entries=new Map(),mapRef=null,lightRef=null,revision=null;return{clear(){entries.clear()},collect(map,observers,lights,epoch){if(map!==mapRef||lights!==lightRef||epoch!==revision){entries.clear();mapRef=map;lightRef=lights;revision=epoch}let sight=new Map(),allowed=new Set(),vision=new Set(),individual=new Map(),recomputed=0;for(let a of observers){let key=JSON.stringify([Math.round(a.x*4),Math.round(a.y*4),Math.round((a.facing||0)*24/Math.PI),Math.round(W.elevation(a,map)*10),a.w,a.d,W.eyeHeight(a),a.vision]);let entry=entries.get(a.id);if(!entry||entry.key!==key){let tiles=new Map(),p=W.center(a),range=a.vision?.range||12,r=Math.max(a.vision?.near??3.5,Math.min(range+12,a.vision?.far??range+6));for(let x=Math.max(0,Math.floor(p.x-r-1));x<Math.min(map.width,Math.ceil(p.x+r+1));x++)for(let y=Math.max(0,Math.floor(p.y-r-1));y<Math.min(map.height,Math.ceil(p.y+r+1));y++){if(Math.hypot(x+.5-p.x,y+.5-p.y)>r+1)continue;tiles.set(W.cellKey(x,y),perceive(map,a,x,y,lights))}entry={key,tiles};entries.set(a.id,entry);recomputed++}individual.set(a.id,entry.tiles);for(let[k,v]of entry.tiles){if(v.allowed)allowed.add(k);if(v.detail>0||v.haze>0){let old=sight.get(k);sight.set(k,{detail:Math.max(old?.detail||0,v.detail),haze:Math.max(old?.haze||0,v.haze)})}if(v.detail>.25||v.haze>.1)vision.add(k)}}let ids=new Set(observers.map(a=>a.id));for(let id of entries.keys())if(!ids.has(id))entries.delete(id);return{sight,allowed,vision,individual,recomputed}}}}
